package com.bhamane.bridalstore.data
import android.content.Context
import androidx.room.Room
import kotlinx.coroutines.flow.Flow
import java.text.SimpleDateFormat
import java.util.*
class StoreRepository private constructor(private val db:StoreDatabase){private val dao=db.dao();val sales:Flow<List<SaleWithItems>> = dao.observeSales();val rentals:Flow<List<RentalEntity>> = dao.observeRentals()
 suspend fun createSale(date:Long,customer:String,phone:String,address:String,items:List<Triple<String,Int,Double>>,discount:Double):SaleWithItems{val subtotal=items.sumOf{it.second*it.third};val saleId=dao.insertSale(SaleEntity(date=date,customerName=customer,phone=phone,address=address,subtotal=subtotal,discount=discount,finalTotal=(subtotal-discount).coerceAtLeast(0.0)));val bill="BBS-"+SimpleDateFormat("yyyyMMdd",Locale.US).format(Date(date))+"-"+saleId.toString().padStart(4,'0');val sale=SaleEntity(id=saleId,billNumber=bill,date=date,customerName=customer,phone=phone,address=address,subtotal=subtotal,discount=discount,finalTotal=(subtotal-discount).coerceAtLeast(0.0));dao.updateSale(sale);val mapped=items.map{SaleItemEntity(saleId=saleId,name=it.first,quantity=it.second,unitPrice=it.third,lineTotal=it.second*it.third)};dao.insertItems(mapped);return SaleWithItems(sale,mapped)}
 suspend fun createRental(item:String,photo:String?,customer:String,phone:String,address:String,start:Long,ret:Long,price:Double){val id=dao.insertRental(RentalEntity(itemName=item,photoUri=photo,customerName=customer,phone=phone,address=address,startDate=start,returnDate=ret,rentalPrice=price));val n="BBR-"+SimpleDateFormat("yyyyMMdd",Locale.US).format(Date(start))+"-"+id.toString().padStart(4,'0');dao.updateRental(RentalEntity(id=id,rentalNumber=n,itemName=item,photoUri=photo,customerName=customer,phone=phone,address=address,startDate=start,returnDate=ret,rentalPrice=price))}
 suspend fun totals(from:Long,to:Long)=Pair(dao.salesTotal(from,to),dao.rentalTotal(from,to));suspend fun allSales()=dao.allSales();suspend fun allRentals()=dao.allRentals();suspend fun dueRentals(before:Long)=dao.dueRentals(before)
 companion object{@Volatile private var INSTANCE:StoreRepository?=null;fun get(context:Context)=INSTANCE?:synchronized(this){INSTANCE?:StoreRepository(Room.databaseBuilder(context.applicationContext,StoreDatabase::class.java,"bhamane_store.db").fallbackToDestructiveMigration().build()).also{INSTANCE=it}}}}
